<?php require '../config.php';admin_required();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$c=strtoupper(trim($_POST['slot_code']??''));$f=trim($_POST['floor']??'Ground Floor');$z=trim($_POST['zone']??'A');$t=$_POST['vehicle_type']??'Any';$r=(float)($_POST['hourly_rate']??0);if(!$c||$r<=0)$err='Enter a slot code and valid rate.';else{try{$s=$pdo->prepare('INSERT INTO parking_slots(slot_code,floor,zone,vehicle_type,hourly_rate) VALUES(?,?,?,?,?)');$s->execute([$c,$f,$z,$t,$r]);go('dashboard.php?added=1');}catch(Throwable $x){$err='That slot code already exists.';}}}$page_title='Add Parking Slot';require '../includes/header.php';?><div class="form-wrap"><div class="form-card"><span class="eyebrow">SPACE MANAGEMENT</span><h1>Add a new slot.</h1><p>New slots become immediately available to drivers.</p><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form method="post"><div class="two"><div class="field"><label>Slot code</label><input name="slot_code" placeholder="D-01" required></div><div class="field"><label>Zone</label><input name="zone" value="D"></div></div><div class="field"><label>Floor</label><input name="floor" value="Ground Floor"></div><div class="two"><div class="field"><label>Vehicle type</label><select name="vehicle_type"><option>Any</option><option>Car</option><option>Bike</option><option>SUV</option><option>EV</option></select></div><div class="field"><label>Hourly rate (₹)</label><input type="number" name="hourly_rate" value="40" min="1" required></div></div><button class="btn primary" style="width:100%">Add parking slot →</button><a class="btn light" style="width:100%;text-align:center;margin-top:10px" href="dashboard.php">Cancel</a></form></div></div><?php require '../includes/footer.php';?>
